(function registerNotoCjkJpPdfFont(root) {
  'use strict';

  const fonts = {
    'NotoSansCJKJP-Regular.subset.ttf': ' '.trim(),
    'NotoSansCJKJP-Bold.subset.ttf': ' '.trim(),
  };

  function register(pdfMake) {
    if (!pdfMake || typeof pdfMake.addVirtualFileSystem !== 'function' || typeof pdfMake.addFonts !== 'function') return false;
    pdfMake.addVirtualFileSystem(fonts);
    pdfMake.addFonts({
      NotoSansCJKJP: {
        normal: 'NotoSansCJKJP-Regular.subset.ttf',
        bold: 'NotoSansCJKJP-Bold.subset.ttf',
        italics: 'NotoSansCJKJP-Regular.subset.ttf',
        bolditalics: 'NotoSansCJKJP-Bold.subset.ttf',
      },
    });
    return true;
  }

  root.AILabourPowerBudgetPdfFonts = { register };
  if (root.pdfMake) register(root.pdfMake);

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { fonts, register };
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);
